const navbar=document.querySelector(".navbar");const navbarContainer=document.querySelector(".navbar-container");const brandLogoParent=document.querySelector(".brand-logo-parent");const brandLogo=document.querySelector(".navbar-brand-logo");const navbarBtn=document.querySelector(".navbar-toggler");const searchBarContainer=document.querySelector(".search-bar-container");const searchBar=document.querySelector(".search-bar");const searchIcon=document.querySelector(".search-icon");const navIcons=document.querySelector(".navbar-icons");const cartItemCount=document.querySelector("#cartItemCount");function RevertNavbarChanges(){const navbarDropdown=document.querySelector(".navbar-dropdown");navbarDropdown.classList.replace("dropdown","dropend");brandLogoParent.append(brandLogo);navbar.appendChild(navIcons);navbar.classList.add("rounded-5")}function ModifyNavbar(){const navbarDropdown=document.querySelector(".navbar-dropdown");if(window.innerWidth<=991){navbarDropdown.classList.replace("dropend","dropdown");navbar.insertBefore(brandLogo,navbarBtn);navbar.insertBefore(navIcons,navbarBtn);navbar.classList.remove("rounded-5")}else{RevertNavbarChanges()}}function ShowSearchBar(){if(searchBarContainer.classList.contains("hidden")){searchBarContainer.classList.remove("hidden");searchBar.focus()}else{searchBarContainer.classList.add("hidden")}}window.addEventListener("load",ModifyNavbar);const setCartItemCount=async()=>{try{const res=await axios.get("/user_cart/itemcount");cartItemCount.innerText=res.data.count}catch(err){console.log(err)}};setCartItemCount();window.addEventListener("resize",ModifyNavbar);searchIcon.addEventListener("click",ShowSearchBar);if(document.title!=="Your Cart"){document.body.onscroll=()=>{if(window.scrollY===0)navbar.classList.remove("shadow");else navbar.classList.add("shadow")}}const navbarDropdown=()=>{const dropdownToggle=document.querySelector(".dropdown-toggle");dropdownToggle.addEventListener("click",()=>{const dropdownMenu=document.querySelector(".custom-dropdown-menu");if(dropdownMenu.classList.contains("d-none")){dropdownMenu.classList.replace("d-none","d-block")}else{dropdownMenu.classList.replace("d-block","d-none")}})};navbarDropdown();